const statuses=[['drafts','Saved marking drafts'],['mark','Needs marking'],['resubmitted','Resubmitted'],['late','Late submissions'],['missing','Missing'],['transfer','Ready for MIS']];
export function filterMarkingInbox(data,params){
 const status=statuses.some(([k])=>k===params.get('status'))?params.get('status'):'mark',classId=params.get('classId')||'',search=(params.get('search')||'').trim().slice(0,120).toLocaleLowerCase();
 const filtered=(status==='drafts'?data.markingDrafts||[]:data.inbox||[]).filter(x=>(status==='drafts'?true:status==='missing'?x.missing:status==='transfer'?x.returned:!x.returned&&!x.missing&&(status==='resubmitted'?x.resubmitted:status==='late'?x.late:true))&&(!classId||x.classId===classId)&&(!search||[x.studentName,x.title,x.className].join(' ').toLocaleLowerCase().includes(search)));
 const limit=12,total=filtered.length,raw=params.get('offset')||'0',requested=/^\d{1,8}$/.test(raw)?Number(raw):0,offset=total?Math.min(Math.floor(requested/limit)*limit,Math.floor((total-1)/limit)*limit):0;
 return{items:filtered.slice(offset,offset+limit),status,classId,search,total,offset,limit};
}
export function createMarkingInboxUI({e,ui,link}){
 function page(data,params,metrics){
  if(data.student)return '<p>The marking inbox is for teachers. '+link('Open your learning tasks',{view:'today'})+'</p>';
  const d=filterMarkingInbox(data,params),classes=[...new Map((data.tasks||[]).map(t=>[t.classId,{id:t.classId,name:t.className}])).values()].sort((a,b)=>a.name.localeCompare(b.name)),paging={view:'inbox',status:d.status,...(d.classId?{classId:d.classId}:{}),...(d.search?{search:d.search}:{}),...(params.get('date')?{date:params.get('date')}:{})};
  return '<p class="muted">Totals across all your classes</p>'+metrics+'<div class="learning-section-title"><h2>Marking inbox</h2>'+link('Saved marking ('+(data.markingDrafts?.length||0)+')',{view:'inbox',status:'drafts'})+'<button type="button" class="btn" data-inbox-refresh>Refresh</button></div><p>Find a student or task, then open their work. Returning feedback keeps MIS transfer under your control.</p><form id="marking-inbox-filters" class="community-filters">'+('<label>As of<input type="date" name="date" value="'+e(data.date)+'" required></label>')+'<label>Show<select name="status" aria-label="Submission status">'+statuses.map(([k,t])=>'<option value="'+k+'" '+(d.status===k?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Class<select name="classId" aria-label="Class to mark"><option value="">All my classes</option>'+classes.map(c=>'<option value="'+e(c.id)+'" '+(d.classId===c.id?'selected':'')+'>'+e(c.name)+'</option>').join('')+'</select></label><label>Find<input name="search" aria-label="Find student or task" maxlength="120" placeholder="Student, task or class" value="'+e(d.search)+'"></label><button type="submit" class="btn">Find work</button>'+link('Clear filters',{view:'inbox',...(params.get('date')?{date:params.get('date')}:{})})+'</form><div class="learning-section-title"><strong>'+d.total+' matching '+(d.total===1?'submission':'submissions')+'</strong><span>'+(d.total?(d.offset+1)+'–'+Math.min(d.total,d.offset+d.limit)+' of '+d.total:'')+'</span></div><section class="vle-panel table-wrap"><table class="data-table inbox-table"><thead><tr><th scope="col">Student</th><th scope="col">Task / class</th><th scope="col">Status</th><th scope="col">Open</th></tr></thead><tbody>'+d.items.map(x=>'<tr><td>'+e(x.studentName)+'</td><td>'+link(x.title,{class:x.classId,assignment:x.id,review:x.studentId})+'<small>'+e(x.className)+'</small></td><td>'+(x.markingDraft?(x.withdrawn?'Student withdrew work · review again':x.stale?'Submission changed · review again':'Private marking draft saved'):x.missing?'Missing':x.returned?'Returned · '+x.mark:x.resubmitted?'Resubmitted':x.late?'Late submission':'Ready to mark')+'</td><td>'+link(x.markingDraft?'Resume marking':x.returned?'Review MIS transfer':'Open work',{class:x.classId,...(x.returned&&!x.markingDraft?{transfer:x.id}:{assignment:x.id,review:x.studentId})})+'</td></tr>').join('')+'</tbody></table>'+(!d.items.length?'<p class="learning-empty">No submissions match this view. Try another status, class or search.</p>':'')+'</section><div class="vle-actions">'+(d.offset?link('← Previous',{...paging,offset:Math.max(0,d.offset-d.limit)}):'')+(d.offset+d.limit<d.total?link('Next →',{...paging,offset:d.offset+d.limit}):'')+'</div>';
 }
 function bind(root){root.querySelector('[data-inbox-refresh]')?.addEventListener('click',()=>ui.render());root.querySelector('#marking-inbox-filters')?.addEventListener('submit',ev=>{ev.preventDefault();const q=new URLSearchParams({view:'inbox'});for(const [k,v]of new FormData(ev.currentTarget))if(v)q.set(k,v);const target='#/classroom?'+q;if(location.hash===target)ui.render();else location.hash=target;});}
 return{page,bind};
}

